-- Isolated fixtures in a transaction; never reset an account or truncate user data.
begin;
do $$
declare token text:=encode(extensions.gen_random_bytes(32),'hex'); aid uuid; p jsonb; s jsonb; r jsonb; pid uuid; q jsonb; blocked boolean; before_count bigint; device uuid:=gen_random_uuid(); eid uuid; req jsonb; delivery jsonb; restoration jsonb;
begin
 select id into aid from verdelia_private.account limit 1;
 insert into verdelia_private.sessions(token_hash,account_id) values(encode(extensions.digest(token,'sha256'),'hex'),aid);
 blocked:=false;begin perform public.verdelia_automation('status','{}');exception when insufficient_privilege then blocked:=true;end;assert blocked,'Automation state must require login';
 assert not has_function_privilege('anon','public.verdelia_background(text,jsonb)','execute'),'Worker exposed to anonymous';
 assert not has_table_privilege('anon','verdelia_private.push_subscriptions','select'),'Push secrets exposed';
 p:=public.verdelia_admin('save_product',jsonb_build_object('session',token,'request_id',gen_random_uuid(),'name','QA product rollback','price',4000,'price_unit','lb','cost',2500,'cost_unit','lb','opening_stock',10,'minimum',2,'target',20,'unit','kg','published',false));pid:=(p->>'id')::uuid;
 assert (p->>'avg_cost')::numeric=5000 and (p->>'price')::numeric=8000,'Cost and sale unit conversion failed';
 s:=public.verdelia_admin('sale',jsonb_build_object('session',token,'request_id',gen_random_uuid(),'lines',jsonb_build_array(jsonb_build_object('id',pid,'quantity',2,'unit','lb')),'method','efectivo'));
 assert (s->>'total')::numeric=8000 and (s->>'cost')::numeric=5000,'Historical snapshots failed';
 req:=jsonb_build_object('session',token,'request_id',gen_random_uuid(),'id',pid,'kind','product','unit','kg','name','QA corrected','price',4500,'price_unit','lb','cost',3,'cost_unit','g','stock_count',8,'minimum',2,'target',20,'note','Correction rollback test');
 r:=public.verdelia_admin('save_product',req);
 assert (select avg_cost from verdelia_private.products where id=pid)=3000,'Edited cost was not persisted';
 assert (select price from verdelia_private.products where id=pid)=9000,'Edited sale price was not persisted';
 assert (select stock from verdelia_private.products where id=pid)=8,'Stock count correction failed';
 assert (select cost from verdelia_private.sales where id=(s->>'id')::uuid)=5000,'Historical cost was rewritten';
 perform public.verdelia_admin('save_product',req);
 assert (select stock from verdelia_private.products where id=pid)=8,'Retry double adjusted inventory';
 assert exists(select 1 from verdelia_private.audit where action='product_correction' and reference_id=pid),'Cost correction audit missing';
 blocked:=false;begin perform public.verdelia_admin('save_product',req||jsonb_build_object('request_id',gen_random_uuid(),'unit','und','cost_unit','und','price_unit','und'));exception when others then blocked:=true;end;assert blocked,'Changed historical base unit';
 blocked:=false;begin perform public.verdelia_admin('save_product',req||jsonb_build_object('request_id',gen_random_uuid(),'cost',4,'note',''));exception when others then blocked:=true;end;assert blocked,'Missing correction reason was accepted';
 p:=public.verdelia_admin('save_product',jsonb_build_object('session',token,'request_id',gen_random_uuid(),'name','QA relabel rollback','price',4000,'cost',2500,'opening_stock',1,'unit','kg','minimum',0,'target',0));
 r:=public.verdelia_admin('save_product',jsonb_build_object('session',token,'request_id',gen_random_uuid(),'id',p->>'id','name','QA relabel rollback','price',4000,'cost',2500,'unit','und','note','Presentation corrected'));
 assert r->>'unit'='und','Unused presentation cannot be corrected';
 -- No network requests commit: net queue writes also roll back.
 insert into verdelia_private.push_subscriptions(id,endpoint,p256dh,auth,label) values(device,'https://web.push.apple.com/qa-rollback',repeat('A',87),repeat('A',22),'QA rollback');
 eid:=verdelia_private.enqueue_push('test','QA','QA','ajustes','qa:'||device,device);
 assert exists(select 1 from verdelia_private.push_deliveries where event_id=eid and subscription_id=device),'Outbox missing';
 assert verdelia_private.enqueue_push('test','QA','QA','ajustes','qa:'||device,device) is null,'Duplicate event emitted';
 perform verdelia_private.automation_tick();
 select count(*) into before_count from verdelia_private.push_events where kind='stock';
 update verdelia_private.products set stock=2 where id=pid;
 perform verdelia_private.automation_tick();
 assert (select count(*) from verdelia_private.push_events where kind='stock')=before_count+1,'Low stock transition missing';
 perform verdelia_private.automation_tick();
 assert (select count(*) from verdelia_private.push_events where kind='stock')=before_count+1,'Low stock repeated';
 update verdelia_private.products set stock=0 where id=pid;
 perform verdelia_private.automation_tick();
 assert (select count(*) from verdelia_private.push_events where kind='stock')=before_count+2,'Out of stock transition missing';
 update verdelia_private.products set stock=2,published=true where id=pid;
 req:=jsonb_build_object('request_id',gen_random_uuid(),'customer','QA rollback','phone','3000000000','delivery_type','pickup','lines',jsonb_build_array(jsonb_build_object('id',pid,'quantity',1,'unit','kg')));
 r:=public.verdelia_order(req);perform public.verdelia_order(req);
 assert (select count(*) from verdelia_private.push_events where dedupe='order:'||(r->>'id'))=1,'Order event missing or duplicated';
 q:=verdelia_private.background('claim_push','{}');
 select value into delivery from jsonb_array_elements(q) where value->>'event_id'=eid::text;
 assert delivery is not null,'Push delivery was not claimed';
 perform verdelia_private.background('ack_push',delivery||jsonb_build_object('ok',true));
 assert exists(select 1 from verdelia_private.push_deliveries where event_id=eid and status='sent'),'Push acknowledgement failed';
 perform public.verdelia_admin('settings',jsonb_build_object('session',token,'request_id',gen_random_uuid(),'name','QA rollback'));
 perform public.verdelia_admin('preferences',jsonb_build_object('session',token,'request_id',gen_random_uuid(),'stock',true));
 q:=verdelia_private.backup_payload();
 restoration:=verdelia_private.restore_backup_to_schema(q,'verdelia_restore_qa_complete');
 assert restoration=q->'row_counts','Recovery validation failed';
 assert q->>'format'='verdelia-business-backup';
 assert jsonb_array_length(q->'tables'->'products')=(select count(*) from verdelia_private.products),'Backup truncated products';
 assert not(q->'tables' ? 'account') and not(q->'tables' ? 'sessions'),'Backup includes credentials';
 assert jsonb_array_length(q->'tables'->'sales')=(select count(*) from verdelia_private.sales),'Backup truncated history';
end $$;
rollback;
select 'PASS: editable cost and price units, stock correction, historical snapshots, audit, idempotency, auth, outbox, stock transitions, complete business backup' result;
